"""Operational CLI: `python -m talkscene.cli <command>`.

The commands CI and the Makefile need, with no extra dependency on a CLI
framework.
"""

from __future__ import annotations

import argparse
import asyncio
import json
import sys
from pathlib import Path

from . import __version__


async def _export_openapi(target: Path) -> int:
    """Export the contract (ADR 0001). CI diffs the result against the commit."""
    import yaml

    from .main import create_app

    spec = create_app().openapi()
    header = (
        "# Generated by `make openapi` from the Pydantic schemas in apps/api.\n"
        "# Do not edit by hand - see docs/adr/0001-openapi-single-source-of-truth.md\n"
    )
    body = header + yaml.safe_dump(spec, sort_keys=False, allow_unicode=True, width=100)

    def _write() -> None:
        target.parent.mkdir(parents=True, exist_ok=True)
        target.write_text(body, encoding="utf-8")

    await asyncio.to_thread(_write)
    paths = len(spec.get("paths", {}))
    schemas = len(spec.get("components", {}).get("schemas", {}))
    print(f"wrote {target} ({paths} paths, {schemas} schemas)")
    return 0


async def _validate_scenarios() -> int:
    from .catalog import loader

    files = loader.discover()
    errors: list[str] = []
    by_language: dict[str, int] = {}
    for path in files:
        try:
            doc = loader.load_file(path)
        except Exception as exc:
            errors.append(f"{path.name}: {exc}")
            continue
        by_language[doc["language"]] = by_language.get(doc["language"], 0) + 1

    for error in errors:
        print(f"  ERROR {error}", file=sys.stderr)
    counts = " ".join(f"{k}={v}" for k, v in sorted(by_language.items()))
    print(f"{len(files)} scenario file(s): {counts}  |  {len(errors)} error(s)")
    return 1 if errors else 0


async def _seed() -> int:
    from .catalog import loader
    from .core.db import create_all, dispose, get_sessionmaker

    await create_all()
    async with get_sessionmaker()() as db:
        result = await loader.sync(db)
        await db.commit()
    await dispose()
    print(json.dumps(result.as_dict(), indent=2))
    return 1 if result.errors else 0


async def _providers() -> int:
    from .providers.registry import get_router

    health = await get_router().health()
    width = max(len(h.provider) for h in health) + 2
    print(f"{'capability':<12}{'provider':<{width}}{'state':<14}configured")
    for item in sorted(health, key=lambda h: (h.capability, h.provider)):
        print(
            f"{item.capability:<12}{item.provider:<{width}}{item.state:<14}"
            f"{'yes' if item.configured else 'no'}"
        )
    return 0


async def _purge_audio(days: int | None) -> int:
    from .core.config import settings
    from .core.storage import get_storage

    removed = await get_storage().purge_older_than(days or settings.audio_retention_days)
    print(f"removed {removed} expired audio object(s)")
    return 0


def main(argv: list[str] | None = None) -> int:
    parser = argparse.ArgumentParser(prog="talkscene", description="TalkScene API operations")
    parser.add_argument("--version", action="version", version=__version__)
    sub = parser.add_subparsers(dest="command", required=True)

    export = sub.add_parser("export-openapi", help="write the OpenAPI contract to a file")
    export.add_argument("target", nargs="?", default="../../docs/openapi.yaml", type=Path)

    sub.add_parser("validate-scenarios", help="validate every scenario pack")
    sub.add_parser("seed", help="create tables and load the scenario packs")
    sub.add_parser("providers", help="show which providers are configured and healthy")

    purge = sub.add_parser("purge-audio", help="delete audio past its retention window")
    purge.add_argument("--days", type=int, default=None)

    args = parser.parse_args(argv)
    match args.command:
        case "export-openapi":
            return asyncio.run(_export_openapi(Path(args.target)))
        case "validate-scenarios":
            return asyncio.run(_validate_scenarios())
        case "seed":
            return asyncio.run(_seed())
        case "providers":
            return asyncio.run(_providers())
        case "purge-audio":
            return asyncio.run(_purge_audio(args.days))
    return 2


if __name__ == "__main__":
    raise SystemExit(main())
